-- =====================================================================
-- HCM UI-supporting seed data.
--   1. eg_userrole_v1 : grants 9 functional admin roles to the SYSTEM
--                       user so the Workbench home renders home cards.
--   2. eg_mdms_data   : ~6,288 rows of ACCESSCONTROL-ACTIONS-TEST.actions-test
--                       (1,572 actions × 4 tenants) pulled from UAT.
--                       egov-accesscontrol resolves home cards from these.
--   3. public.message : ~19,551 localization rows for the modules the
--                       Workbench UI requests on boot
--                       (rainmaker-common, digit-ui × 4 locales).
--
-- Loaded automatically by Postgres on first start via
-- /docker-entrypoint-initdb.d. Statements are idempotent
-- (ON CONFLICT DO NOTHING / batched DELETE+INSERT).
-- =====================================================================

-- Grant 9 functional admin roles to the seeded SYSTEM user (id=1, uuid dc6fffba-…)
-- so the Workbench home renders cards. SUPERUSER alone has no cards mapped.
-- eg_userrole_v1 has no unique constraint, so use WHERE NOT EXISTS for idempotency.
BEGIN;
SELECT r.code, 'mz', 1, 'mz', now()
FROM eg_role r
WHERE r.tenantid='mz'
  AND r.code IN (
    'CAMPAIGN_ADMIN','CAMPAIGN_MANAGER','HRMS_ADMIN','LOC_ADMIN',
    'MDMS_ADMIN','BOUNDARY_MANAGER','MICROPLAN_CAMPAIGN_INTEGRATOR',
    'HELPDESK_USER','PGR-ADMIN'
  )
  AND NOT EXISTS (
    SELECT 1 FROM eg_userrole_v1 u
    WHERE u.user_id=1 AND u.user_tenantid='mz'
      AND u.role_code=r.code AND u.role_tenantid='mz'
  );
COMMIT;
-- 6288 rows for 4 tenants × 1572 actions
BEGIN;
DELETE FROM eg_mdms_data WHERE schemacode='ACCESSCONTROL-ACTIONS-TEST.actions-test';
COMMIT;
-- 19551 rows from 8 files
BEGIN;
DELETE FROM message WHERE tenantid='mz' AND module='digit-ui' AND locale='en_IN';
DELETE FROM message WHERE tenantid='mz' AND module='digit-ui' AND locale='en_MZ';
DELETE FROM message WHERE tenantid='mz' AND module='digit-ui' AND locale='fr_IN';
DELETE FROM message WHERE tenantid='mz' AND module='digit-ui' AND locale='pt_IN';
DELETE FROM message WHERE tenantid='mz' AND module='rainmaker-common' AND locale='en_IN';
DELETE FROM message WHERE tenantid='mz' AND module='rainmaker-common' AND locale='en_MZ';
DELETE FROM message WHERE tenantid='mz' AND module='rainmaker-common' AND locale='fr_IN';
DELETE FROM message WHERE tenantid='mz' AND module='rainmaker-common' AND locale='pt_IN';
